package vn.edu.fpt.seal.modules.audit.repository; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.stereotype.Repository; import vn.edu.fpt.seal.common.enums.AuditAction; import vn.edu.fpt.seal.modules.audit.entity.AuditLog; import java.util.*;
@Repository public interface AuditLogRepository extends JpaRepository<AuditLog,UUID>{ @EntityGraph(attributePaths={"user","team","incident"}) Page<AuditLog> findByUserId(UUID userId,Pageable p); @EntityGraph(attributePaths={"user","team","incident"}) Page<AuditLog> findByTeamId(UUID teamId,Pageable p); @EntityGraph(attributePaths={"user","team","incident"}) Page<AuditLog> findByIncidentId(UUID incidentId,Pageable p); @EntityGraph(attributePaths={"user","team","incident"}) Page<AuditLog> findByAction(AuditAction action,Pageable p); @EntityGraph(attributePaths={"user","team","incident"}) Optional<AuditLog> findWithRelationsById(UUID id); }
